    public void ShowEditor(ContentSet content,EmpireView view,RequestId? request=null)
    {
        _content=content;_view=view;_request=request;var current=Current();_name.Text=current?.Name??"Assembly fleet";_priority.Select((int)(current?.Priority??RequestPriority.Normal));_cargo.SetPressedNoSignal(current?.AuthorizeCargo??false);_roleIds.Clear();if(current is null){if(view.AvailableVesselRoleIds.Contains("scout"))_roleIds.Add(new("scout",null));else if(!view.AvailableVesselRoleIds.IsEmpty)_roleIds.Add(Quota(view.AvailableVesselRoleIds[0]));}else _roleIds.AddRange(current.Slots.OrderBy(s=>s.Ordinal).Select(s=>new AssemblyQuota(s.RoleId,s.Design)));
        _role.Clear();foreach(string id in view.AvailableVesselRoleIds.Where(id=>!ShipDesignUi.UsesDesigns(content,view,id))){_role.AddItem(_content.Vessels[id].Name);_role.SetItemMetadata(_role.ItemCount-1,id);}foreach(var d in ShipDesignQueries.BuildChoices(view)){_role.AddItem(ShipDesignUi.DesignName(content,view,d.Id));_role.SetItemMetadata(_role.ItemCount-1,ShipDesignUi.Encode(ShipDesignTargets.Build(d.Id)));}if(view.AvailableVesselRoleIds.Contains("scout"))for(int i=0;i<_role.ItemCount;i++)if(_role.GetItemMetadata(i).AsString()=="scout")_role.Select(i);
        _rally.Clear();var initial=current?.Rally??view.Colonies.FirstOrDefault()?.StarId??view.Stars[0].Chart.Id;foreach(var star in view.Stars.OrderBy(s=>s.Chart.Id)){_rally.AddItem($"Rally: {star.Chart.Name} ({(star.LastObservedTurn is {} t?$"survey {t}":"unsurveyed")})");_rally.SetItemMetadata(_rally.ItemCount-1,star.Chart.Id.Value);if(star.Chart.Id==initial)_rally.Select(_rally.ItemCount-1);}
        _rallyFleet.Clear();_rallyFleet.AddItem("Reserve a new named fleet slot");_rallyFleet.SetItemMetadata(0,0);foreach(var f in view.Fleets!.Fleets.OrderBy(f=>f.Id)){_rallyFleet.AddItem($"Existing rally fleet: {f.Name}");_rallyFleet.SetItemMetadata(_rallyFleet.ItemCount-1,f.Id.Value);if(f.Id==current?.RallyFleet)_rallyFleet.Select(_rallyFleet.ItemCount-1);}
        _colonies.Clear();_colonyRows.Clear();foreach(var col in view.Colonies.OrderBy(c=>c.Id)){_colonyRows.Add(col.Id);_colonies.AddItem($"{Colony(col.Id)} — current {Project(col)}, reserve {Format.Points(col.ProductionReserve)}; governor {(col.Development?.ConstructionEnabled==true?"On":"Off")}");if(current?.Colonies.Contains(col.Id)==true||current is null&&_colonies.ItemCount==1)_colonies.Select(_colonies.ItemCount-1,false);}
        _coordinator.Clear();_coordinator.AddItem("No coordinator (fleet tools still work)");_coordinator.SetItemMetadata(0,0);foreach(var o in view.Fleets.Officers.Where(o=>o.Status==OfficerStatus.Posted||o.Status==OfficerStatus.Coordinating&&o.Request==request).OrderBy(o=>o.Id)){_coordinator.AddItem($"{o.Name} — {o.Specialty}, rank{o.Rank}");_coordinator.SetItemMetadata(_coordinator.ItemCount-1,o.Id.Value);if(o.Id==current?.Coordinator)_coordinator.Select(_coordinator.ItemCount-1);}
        foreach(var picker in new[]{_role,_rally,_rallyFleet,_coordinator,_yard,_slot}){picker.FitToLongestItem=false;picker.ClipText=true;picker.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;}
        RoleText();_selectedIdle.Clear();_idlePage=0;_idleNotice.Text="";_idle.Clear();_idleRows.Clear();UpdateView(content,view);Invalidate();PopupCenteredClamped(new(760,560));
    }
    public void UpdateView(ContentSet content,EmpireView view)
    {
        int oldYard=_yard.ItemCount>0?_yard.GetSelectedMetadata().AsInt32():0;int oldSlot=_slot.ItemCount>0?_slot.GetSelectedMetadata().AsInt32():0;_content=content;_view=view;var r=Current();_status.Text=r is null?"New finite quota. Nothing is ordered until you accept a reviewed preview.":$"{r.Name}: {r.Status}; revision{r.Revision}. {r.Attention} Slots: "+string.Join(", ",r.Slots.Select(s=>$"{s.Ordinal}: {s.Status}"));_edit.Visible=r is not null&&FleetQueries.IsActive(r.Status);_accept.Text=r is null?"Accept finite request":"Amend finite quota";_yard.Clear();_slot.Clear();if(r is not null){foreach(var col in r.Colonies){_yard.AddItem($"Yard: {Colony(col)}{(r.PausedContributions.Contains(col)?" — PAUSED":"")}");_yard.SetItemMetadata(_yard.ItemCount-1,col.Value);if(col.Value==oldYard)_yard.Select(_yard.ItemCount-1);}foreach(var slot in r.Slots.Where(s=>s.Vessel is not null)){_slot.AddItem($"Slot {slot.Ordinal}: {(slot.Design is {} design?ShipDesignUi.DesignName(_content,_view,design):_content.Vessels[slot.RoleId].Name)} #{slot.Vessel!.Value.Value} / {slot.Status}");_slot.SetItemMetadata(_slot.ItemCount-1,slot.Ordinal);if(slot.Ordinal==oldSlot)_slot.Select(_slot.ItemCount-1);}}IdleCandidates();
    }
    public void ShowError(string text)=>_error.Text=text;
    private AssemblyRequestView? Current()=>_request is {} id?_view.Fleets!.Requests.SingleOrDefault(r=>r.Id==id):null;
    private IFleetPlanningContext Context()=>FleetPlanningQueries.Create(_content,_view);
    private StarId Rally()=>new(_rally.GetSelectedMetadata().AsInt32());private FleetId? RallyFleet()=>_rallyFleet.GetSelectedMetadata().AsInt32() is int id&&id>0?new(id):null;
    private AssemblyDraft Draft()=>new(_name.Text,Rally(),RallyFleet(),(Rules.HasShipDesigns(_view.RulesVersion)?ImmutableArray<string>.Empty:_roleIds.Select(q=>q.RoleId).ToImmutableArray()),_colonies.GetSelectedItems().Select(i=>_colonyRows[i]).ToImmutableArray(),(RequestPriority)_priority.Selected,_selectedIdle.OrderBy(id=>id).ToImmutableArray(),_cargo.ButtonPressed,_coordinator.GetSelectedMetadata().AsInt32() is int id&&id>0?new(id):null){Quotas=Rules.HasShipDesigns(_view.RulesVersion)?_roleIds.ToImmutableArray():default};
    private AssemblyQuota Quota(string metadata)=>metadata.StartsWith("ship_design|",StringComparison.Ordinal)?new(_content.ShipDesigns!.WarshipRoleId,new(int.Parse(metadata[12..],System.Globalization.CultureInfo.InvariantCulture))):new(metadata,Rules.HasShipDesigns(_view.RulesVersion)&&metadata==_content.ShipDesigns?.WarshipRoleId?new DesignId(1):null);
    private string QuotaName(AssemblyQuota quota)=>quota.Design is {} id?ShipDesignUi.DesignName(_content,_view,id):_content.Vessels[quota.RoleId].Name;
    private void RoleText()=>_roles.Text=_roleIds.Count==0?"No quota selected.":$"{_roleIds.Count}/32 requested: "+string.Join(", ",_roleIds.GroupBy(id=>id).Select(g=>$"{g.Count()} × {QuotaName(g.Key)}"));
    private void Invalidate(){_preview=null;_draft=null;if(_accept is not null)_accept.Disabled=true;}
    private void IdleCandidates()
    {
        if(_rally.ItemCount==0||_rallyFleet.ItemCount==0||_coordinator.ItemCount==0)return;
        var draft=Draft() with{AcceptedIdleVessels=ImmutableArray<VesselId>.Empty};var preview=AssemblyPlanner.Preview(Context(),draft,_request);
        _idleCandidates=preview.IdleCandidates.Where(ship=>_roleIds.Any(q=>q.RoleId==ship.RoleId&&(!Rules.HasShipDesigns(_view.RulesVersion)||q.Design==ship.Design))).OrderBy(ship=>ship.Id).ToImmutableArray();
        var eligible=_idleCandidates.Select(ship=>ship.Id).ToHashSet();var removed=_selectedIdle.Where(id=>!eligible.Contains(id)).OrderBy(id=>id).ToArray();_selectedIdle.IntersectWith(eligible);
        if(removed.Length>0)_idleNotice.Text="Removed no longer eligible selections: "+string.Join(", ",removed.Select(id=>"#"+id.Value))+". Review the changed quota before accepting.";
        IdleRows();Invalidate();
    }
    private void IdlePageText(){int pages=Math.Max(1,(_idleCandidates.Length+31)/32);_idlePages.Text=$"Page {_idlePage+1}/{pages}; {_idleCandidates.Length} eligible; {_selectedIdle.Count} selected";_idlePrevious.Disabled=_idlePage==0;_idleNext.Disabled=_idlePage==pages-1;}
    private void IdleRows()
    {
        int pages=Math.Max(1,(_idleCandidates.Length+31)/32);_idlePage=Math.Clamp(_idlePage,0,pages-1);_idle.Clear();_idleRows.Clear();
        foreach(var ship in _idleCandidates.Skip(_idlePage*32).Take(32)){_idleRows.Add(ship.Id);_idle.AddItem($"Use existing {(ship.Design is {} d?ShipDesignUi.DesignName(_content,_view,d):_content.Vessels[ship.RoleId].Name)} #{ship.Id.Value}");_idle.SetItemMetadata(_idle.ItemCount-1,ship.Id.Value);if(_selectedIdle.Contains(ship.Id))_idle.Select(_idle.ItemCount-1,_idle.GetSelectedItems().Length==0);}
        IdlePageText();
        Callable.From(()=>{if(IsInstanceValid(_idle)&&_idle.IsInsideTree()&&_idle.GetSelectedItems().Length>0)_idle.EnsureCurrentIsVisible();}).CallDeferred();
    }
    private bool Allowed(AssemblyPreview preview){_error.Text=string.Join("\n",preview.Rejections);return preview.Allowed;}
    private void Preview(){_draft=Draft();_preview=AssemblyPlanner.Preview(Context(),_draft,_request);_accept.Disabled=!Allowed(_preview);_previewText.Text=Describe(_preview);}
    private string Colony(ColonyId id)=>_view.Research.ColonyNames.TryGetValue(id.ToString(),out var name)?name:$"colony {id.Value}";
    private string Project(OwnedColonyView c)=>c.ProjectId is null?"bank production":ShipDesignUi.Name(_content,_view,new(c.ProjectKind,c.ProjectId));
    private string Describe(AssemblyPreview preview)
    {
        string before=string.Join("\n",preview.Colonies.Select(c=>{var col=_view.Colonies.Single(x=>x.Id==c.Colony);return $"{Colony(c.Colony)}: before {Project(col)}, reserve {Format.Points(c.Reserve)}, population {col.Population}; after acceptance: active work / reserve / population unchanged. Queue before: {string.Join(", ",c.PriorQueue.Select(q=>$"{q.Token}:{q.Target.ContentId}"))}; after: {string.Join(", ",c.ProposedQueue.Select(q=>$"{q.Token?.ToString()??"new"}:{q.Target.ContentId}"))}. Current output {Format.Points(c.ProductionPerTurn)}/turn; planned embark total {c.CargoTotal}.";}));
        string slots=string.Join("\n",preview.Slots.Select(s=>$"Slot {s.Ordinal}: {(s.Design is {} d?ShipDesignUi.DesignName(_content,_view,d):_content.Vessels[s.RoleId].Name)}, cost {Format.Points(s.Cost)}, cargo {s.Cargo}, completion {(s.CompletionTurns?.ToString()??"conditional / stalled")}, arrival {(s.ArrivalTurns?.ToString()??"conditional / unknown")} turn(s)."));
        return before+"\n"+slots+"\n"+string.Join("\n",preview.Warnings)+"\nEstimates assume current output and fixed scope. Actual population maturity, quarantine, manual changes and known danger may delay work; one completion per yard per turn. No future technology or growth is promised.";
    }
    private void Edit(Action<AssemblyRequestView> action){var r=Current();if(r is not null&&FleetQueries.IsActive(r.Status))action(r);else _error.Text="This request is final or unavailable.";}
    private void Yard(bool pause)=>Edit(r=>{if(_yard.ItemCount>0)Confirm(new AssemblyCommand(_view.Viewer,_view.Turn,new AssemblyAction.SetContributionPaused(r.Id,r.Revision,new(_yard.GetSelectedMetadata().AsInt32()),pause)),pause?"Pause only this yard's future contribution. Keep active paid work, reserve, tokens and other yards. Scoped discounts stop while paused.":"Resume only this retained yard contribution; no missing-slot refill or request safety waiver.");});
    private void Confirm(Command command,string text){_pending=command;_confirmationText.Text=text;_confirm.PopupCenteredClamped(new(680,460));}
}
